private function roundHalfUp(string $value, int $precision): string
{
    // bcadd with 0.5 * 10^-precision
    $scale = $precision + 4;
    $factor = bcpow('10', (string)$precision, $scale);
    $num = bcmul($value, $factor, $scale);
    // Determine sign
    $sign = strpos($num, '-') === 0 ? '-' : '';
    $abs = ltrim($num, '-');
    // add 0.5
    $absPlus = bcadd($abs, '0.5', $scale);
    $intPart = bcdiv($absPlus, '1', 0, PHP_ROUND_HALF_UP); // bcdiv with 0 scale?
    // Simpler using bcadd
    // Use fmod
    // We'll use PHP's bcmath round via addition
    // Let's just do:
    $tmp = bcadd($abs, '0.0000005', $precision+10); // not correct
    // Better implement:
    // Use bcscale
    bcscale(20);
    $num = bcmul($value, bcpow('10', (string)$precision));
    // add 0.5
    $num = bcadd($num, '0.5', 0);
    // truncate
    $num = bcdiv($num, '1', 0);
    $num = bcdiv($num, bcpow('10', (string)$precision), $precision);
    return $num;
}

